CREATE OR REPLACE FUNCTION business_documents.guard_evidence_idempotency_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF ROW(NEW.tenant_id, NEW.workspace_id, NEW.client_account_id, NEW.subject_type, NEW.subject_id,
           NEW.requested_by_membership_id, NEW.idempotency_key, NEW.original_filename, NEW.declared_content_type)
       IS DISTINCT FROM
       ROW(OLD.tenant_id, OLD.workspace_id, OLD.client_account_id, OLD.subject_type, OLD.subject_id,
           OLD.requested_by_membership_id, OLD.idempotency_key, OLD.original_filename, OLD.declared_content_type)
       OR (OLD.request_fingerprint IS NOT NULL AND NEW.request_fingerprint IS DISTINCT FROM OLD.request_fingerprint)
       OR (OLD.upload_content_sha256 IS NOT NULL AND NEW.upload_content_sha256 IS DISTINCT FROM OLD.upload_content_sha256) THEN
        RAISE EXCEPTION 'Business evidence idempotency identity is immutable' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION integration.purge_expired_change_events(batch_size integer)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'integration'
AS $function$
DECLARE
    deleted_count BIGINT;
BEGIN
    IF batch_size IS NULL OR batch_size < 1 OR batch_size > 1000 THEN
        RAISE EXCEPTION 'batch_size must be between 1 and 1000';
    END IF;
    PERFORM set_config('nexa.change_feed.maintenance', 'on', true);
    WITH expired AS (
        SELECT ctid FROM integration.change_event
        WHERE expires_at < current_timestamp
        ORDER BY expires_at, "sequence"
        LIMIT batch_size
    )
    DELETE FROM integration.change_event event
    USING expired
    WHERE event.ctid = expired.ctid;
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$function$;

CREATE OR REPLACE FUNCTION logistics.prevent_delivery_handoff_token_mutation_v17()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' OR NEW.id <> OLD.id OR NEW.tenant_id <> OLD.tenant_id
       OR NEW.workspace_id <> OLD.workspace_id OR NEW.delivery_id <> OLD.delivery_id
       OR NEW.delivery_attempt_id <> OLD.delivery_attempt_id
       OR NEW.customer_account_id <> OLD.customer_account_id OR NEW.token_hash <> OLD.token_hash
       OR NEW.issued_at <> OLD.issued_at OR NEW.expires_at <> OLD.expires_at
       OR NEW.issuer_membership_id <> OLD.issuer_membership_id
       OR NEW.idempotency_key <> OLD.idempotency_key OR NEW.request_hash <> OLD.request_hash
       OR NEW.created_at <> OLD.created_at
       OR OLD.status <> 'ACTIVE' OR NEW.status NOT IN ('REPLACED','EXPIRED','CONSUMED') THEN
        RAISE EXCEPTION 'Delivery handoff token binding is immutable';
    END IF;
    RETURN NEW;
END;
$function$;

