CREATE OR REPLACE FUNCTION logistics.require_current_driver_arrival_attempt()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.event_type = 'DRIVER_ARRIVED' AND NOT EXISTS (
        SELECT 1
        FROM logistics.delivery_active_attempt a
        JOIN logistics.delivery_assignment d
          ON d.tenant_id = a.tenant_id
         AND d.workspace_id = a.workspace_id
         AND d.delivery_id = a.delivery_id
         AND d.responsible_membership_id = a.started_by_membership_id
        WHERE a.tenant_id = NEW.tenant_id
          AND a.workspace_id = NEW.workspace_id
          AND a.delivery_id = NEW.delivery_id
          AND a.id = NEW.attempt_id
          AND a.started_by_membership_id = NEW.actor_membership_id
    ) THEN
        RAISE EXCEPTION 'Driver arrival requires the current assigned attempt';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION logistics.validate_driver_delivery_incident_attempt()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM logistics.delivery_active_attempt active
        WHERE active.tenant_id=NEW.tenant_id AND active.workspace_id=NEW.workspace_id
          AND active.delivery_id=NEW.delivery_id AND active.id=NEW.delivery_attempt_id
    ) AND NOT EXISTS (
        SELECT 1 FROM logistics.delivery_attempt terminal
        WHERE terminal.tenant_id=NEW.tenant_id AND terminal.workspace_id=NEW.workspace_id
          AND terminal.delivery_id=NEW.delivery_id AND terminal.id=NEW.delivery_attempt_id
    ) THEN
        RAISE EXCEPTION 'Driver incident attempt is outside its delivery scope';
    END IF;
    RETURN NEW;
END;
$function$;

