CREATE OR REPLACE FUNCTION sales.assign_purchase_request_expiry()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    expiry_days integer;
BEGIN
    IF NEW.status <> 'DRAFT' AND NEW.expires_at IS NULL THEN
        SELECT purchase_request_expiry_days
          INTO expiry_days
          FROM tenant_management.operational_settings
         WHERE workspace_id = NEW.workspace_id;
        NEW.expires_at := coalesce(NEW.submitted_at, NEW.created_at, current_timestamp)
            + make_interval(days => coalesce(expiry_days, 3));
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION sales.expire_open_material_change_on_terminal_request()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.status IN ('CONVERTED','CONVERTED_TO_ORDER','REJECTED','WITHDRAWN','EXPIRED','CANCELLED')
       AND OLD.status IS DISTINCT FROM NEW.status THEN
        UPDATE sales.purchase_request_material_change
           SET status='EXPIRED', resolved_at=NEW.updated_at, resolved_request_version=NEW.version
         WHERE tenant_id=NEW.tenant_id AND workspace_id=NEW.workspace_id
           AND purchase_request_id=NEW.id AND status='PROPOSED';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION sales.prevent_append_only_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_TABLE_SCHEMA = 'integration'
        AND TG_TABLE_NAME = 'change_event'
        AND TG_OP = 'DELETE'
        AND current_setting('nexa.change_feed.maintenance', true) = 'on' THEN
        RETURN OLD;
    END IF;
    RAISE EXCEPTION 'Append-only record cannot be changed';
END;
$function$;

