        OR NEW.priority IS DISTINCT FROM OLD.priority
        OR NEW.requested_delivery_date IS DISTINCT FROM OLD.requested_delivery_date
        OR NEW.delivery_snapshot IS DISTINCT FROM OLD.delivery_snapshot
