CREATE OR REPLACE FUNCTION warehouse.guard_inbound_discrepancy_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'inbound receiving discrepancy facts are append-only';
    END IF;
    IF ROW(NEW.id, NEW.tenant_id, NEW.workspace_id, NEW.warehouse_id, NEW.expected_sku_id, NEW.observed_sku_id,
           NEW.expected_batch_reference, NEW.observed_batch_reference, NEW.expected_quantity, NEW.observed_quantity,
           NEW.unit, NEW.reason, NEW.observation_notes, NEW.recorded_by_membership_id, NEW.recorded_at,
           NEW.create_idempotency_key, NEW.create_request_hash)
       IS DISTINCT FROM
       ROW(OLD.id, OLD.tenant_id, OLD.workspace_id, OLD.warehouse_id, OLD.expected_sku_id, OLD.observed_sku_id,
           OLD.expected_batch_reference, OLD.observed_batch_reference, OLD.expected_quantity, OLD.observed_quantity,
           OLD.unit, OLD.reason, OLD.observation_notes, OLD.recorded_by_membership_id, OLD.recorded_at,
           OLD.create_idempotency_key, OLD.create_request_hash) THEN
        RAISE EXCEPTION 'inbound receiving discrepancy observations are immutable';
    END IF;
    IF NOT (OLD.status = 'PENDING_EVIDENCE' AND NEW.status = 'READY_FOR_REVIEW'
            AND OLD.version = 0 AND NEW.version = 1 AND OLD.evidence_object_id IS NULL
            AND NEW.evidence_object_id IS NOT NULL AND OLD.submitted_by_membership_id IS NULL
            AND NEW.submitted_by_membership_id IS NOT NULL AND OLD.submitted_at IS NULL
            AND NEW.submitted_at IS NOT NULL AND OLD.submit_idempotency_key IS NULL
            AND NEW.submit_idempotency_key IS NOT NULL AND OLD.submit_request_hash IS NULL
            AND NEW.submit_request_hash IS NOT NULL) THEN
        RAISE EXCEPTION 'invalid inbound receiving discrepancy transition';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION warehouse.guard_inventory_transfer_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status IS DISTINCT FROM 'REQUESTED' THEN
            RAISE EXCEPTION 'warehouse inventory transfers must begin as REQUESTED';
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'warehouse inventory transfers cannot be deleted';
    END IF;

    IF OLD.status = 'REQUESTED' AND NEW.status = 'IN_TRANSIT' THEN
        IF NEW.version <> OLD.version + 1
            OR NEW.transferred_quantity <> NEW.requested_quantity
            OR NEW.dispatched_at IS NULL
            OR NEW.source_quantity_after IS NULL
            OR NEW.source_version_after IS NULL
            OR NEW.source_lot_status_at_dispatch IS NULL
            OR NEW.received_at IS NOT NULL
            OR NEW.destination_lot_id IS NOT NULL THEN
            RAISE EXCEPTION 'invalid warehouse transfer dispatch transition';
        END IF;
        IF (to_jsonb(NEW) - ARRAY['status','version','transferred_quantity','source_quantity_before',
                'source_quantity_after','source_version_after','dispatched_at','source_lot_status_at_dispatch'])
            IS DISTINCT FROM
           (to_jsonb(OLD) - ARRAY['status','version','transferred_quantity','source_quantity_before',
                'source_quantity_after','source_version_after','dispatched_at','source_lot_status_at_dispatch']) THEN
            RAISE EXCEPTION 'warehouse transfer request facts are immutable';
        END IF;
    ELSIF OLD.status = 'IN_TRANSIT' AND NEW.status = 'RECEIVED' THEN
        IF NEW.version <> OLD.version + 1
            OR NEW.transferred_quantity <> OLD.transferred_quantity
            OR NEW.source_version_after <> OLD.source_version_after
            OR NEW.source_quantity_before <> OLD.source_quantity_before
            OR NEW.source_quantity_after <> OLD.source_quantity_after
            OR NEW.source_lot_status_at_dispatch <> OLD.source_lot_status_at_dispatch
            OR NEW.dispatched_at <> OLD.dispatched_at
            OR NEW.received_at IS NULL
            OR NEW.completed_at IS NULL
            OR NEW.destination_lot_id IS NULL
            OR NEW.destination_quantity_before IS NULL
            OR NEW.destination_quantity_after IS NULL
            OR NEW.destination_version_after IS NULL THEN
            RAISE EXCEPTION 'invalid warehouse transfer receipt transition';
        END IF;
        IF (to_jsonb(NEW) - ARRAY['status','version','destination_lot_id','destination_quantity_before',
                'destination_quantity_after','destination_version_after','received_at','completed_at'])
            IS DISTINCT FROM
           (to_jsonb(OLD) - ARRAY['status','version','destination_lot_id','destination_quantity_before',
                'destination_quantity_after','destination_version_after','received_at','completed_at']) THEN
            RAISE EXCEPTION 'warehouse transfer dispatch facts are immutable';
        END IF;
    ELSE
        RAISE EXCEPTION 'invalid warehouse transfer state transition';
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION warehouse.validate_reservation_allocation_scope()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM warehouse.inventory_reservation_line line
        JOIN warehouse.inventory_reservation reservation ON reservation.id = line.reservation_id
        JOIN warehouse.inventory_lot lot ON lot.id = NEW.lot_id
        WHERE line.id = NEW.reservation_line_id
          AND reservation.tenant_id = lot.tenant_id
          AND reservation.workspace_id = lot.workspace_id
          AND line.sku_id = lot.sku_id
          AND NEW.unit = line.unit
          AND NEW.unit = lot.unit
    ) THEN
        RAISE EXCEPTION 'Reservation allocation crosses SKU, unit or tenant/workspace boundary';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION warehouse.validate_reservation_line_sku_scope()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM warehouse.inventory_reservation reservation
        JOIN catalog_management.sellable_sku sku
          ON sku.id = NEW.sku_id
         AND sku.tenant_id = reservation.tenant_id
         AND sku.workspace_id = reservation.workspace_id
        WHERE reservation.id = NEW.reservation_id
    ) THEN
        RAISE EXCEPTION 'Reservation line SKU is outside the reservation tenant/workspace';
    END IF;
    RETURN NEW;
END;
$function$;

