--

CREATE TABLE logistics.temperature_evidence (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    delivery_id uuid,
    lot_id uuid,
    value numeric,
    temperature_celsius numeric,
    unit character varying(16) NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    source character varying(64) DEFAULT 'MANUAL'::character varying NOT NULL,
    evidence_metadata text,
    status character varying(16) NOT NULL,
    evidence_object_id uuid,
    actor_membership_id uuid NOT NULL,
    created_at timestamp with time zone NOT NULL,
    subject_type character varying(16) NOT NULL,
    subject_id uuid NOT NULL,
    warehouse_id uuid,
    zone_id uuid,
    fulfillment_id uuid,
    fulfillment_version bigint,
    expected_lot_version bigint,
    resulting_lot_version bigint,
    inventory_temperature_evaluation_id uuid,
    inventory_lot_status character varying(16),
    affected_quantity numeric(19,4),
    reason character varying(2000),
    source_evidence_id uuid,
    CONSTRAINT ck_temperature_evidence_affected_quantity CHECK (((affected_quantity IS NULL) OR (affected_quantity > (0)::numeric))),
    CONSTRAINT ck_temperature_evidence_expected_lot_version CHECK (((expected_lot_version IS NULL) OR (expected_lot_version >= 0))),
    CONSTRAINT ck_temperature_evidence_fulfillment_version CHECK (((fulfillment_version IS NULL) OR (fulfillment_version >= 0))),
    CONSTRAINT ck_temperature_evidence_inventory_lot_status CHECK (((inventory_lot_status IS NULL) OR ((inventory_lot_status)::text = ANY ((ARRAY['AVAILABLE'::character varying, 'HOLD'::character varying])::text[])))),
    CONSTRAINT ck_temperature_evidence_reason CHECK (((reason IS NULL) OR ((length(btrim((reason)::text)) >= 1) AND (length(btrim((reason)::text)) <= 2000)))),
    CONSTRAINT ck_temperature_evidence_resulting_lot_version CHECK (((resulting_lot_version IS NULL) OR (resulting_lot_version >= 0))),
    CONSTRAINT ck_temperature_evidence_status CHECK (((status)::text = ANY ((ARRAY['WITHIN_RANGE'::character varying, 'OUT_OF_RANGE'::character varying, 'UNKNOWN'::character varying])::text[]))),
    CONSTRAINT ck_temperature_evidence_subject CHECK (((((subject_type)::text = 'DELIVERY'::text) AND (delivery_id IS NOT NULL) AND (fulfillment_id IS NULL) AND (fulfillment_version IS NULL) AND (subject_id = delivery_id)) OR (((subject_type)::text = 'FULFILLMENT'::text) AND (delivery_id IS NULL) AND (fulfillment_id IS NOT NULL) AND (fulfillment_version IS NOT NULL) AND (subject_id = fulfillment_id) AND (lot_id IS NOT NULL) AND (warehouse_id IS NOT NULL) AND (zone_id IS NOT NULL)) OR (((subject_type)::text = 'LOT'::text) AND (delivery_id IS NULL) AND (fulfillment_id IS NULL) AND (fulfillment_version IS NULL) AND (lot_id IS NOT NULL) AND (warehouse_id IS NOT NULL) AND (zone_id IS NOT NULL) AND (subject_id = lot_id)) OR (((subject_type)::text = 'WAREHOUSE'::text) AND (delivery_id IS NULL) AND (fulfillment_id IS NULL) AND (fulfillment_version IS NULL) AND (lot_id IS NULL) AND (warehouse_id IS NOT NULL) AND (zone_id IS NULL) AND (subject_id = warehouse_id)))),
    CONSTRAINT ck_temperature_evidence_value CHECK (((value IS NULL) OR ((value > ('-1000'::integer)::numeric) AND (value < (1000)::numeric))))
);

