--

COMMENT ON COLUMN logistics.temperature_evidence.inventory_temperature_evaluation_id IS 'Opaque identifier of the BC-05-owned excursion evaluation; there is intentionally no cross-context foreign key.';


--
-- Name: COLUMN temperature_evidence.inventory_lot_status; Type: COMMENT; Schema: logistics; Owner: -
--

COMMENT ON COLUMN logistics.temperature_evidence.inventory_lot_status IS 'BC-05 lot status observed after the evidence command; current fulfillment excursion commands can only set HOLD.';


--
