    CONSTRAINT ck_financial_adjustment_balances CHECK (((adjusted_amount >= (0)::numeric) AND (outstanding_amount >= (0)::numeric) AND (receivable_version >= 0))),
    CONSTRAINT ck_financial_adjustment_command_key CHECK (((length(btrim((idempotency_key)::text)) >= 1) AND (length(btrim((idempotency_key)::text)) <= 160))),
    CONSTRAINT ck_financial_adjustment_currency CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT ck_financial_adjustment_effect CHECK (((effect)::text = ANY ((ARRAY['INCREASE'::character varying, 'DECREASE'::character varying])::text[]))),
    CONSTRAINT ck_financial_adjustment_hash CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ck_financial_adjustment_kind CHECK (((adjustment_kind)::text = ANY ((ARRAY['INCREASE'::character varying, 'DECREASE'::character varying, 'WRITE_OFF'::character varying, 'CORRECTION'::character varying])::text[]))),
    CONSTRAINT ck_financial_adjustment_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'APPROVED'::character varying, 'POSTED'::character varying, 'REJECTED'::character varying])::text[])))
);

