CASE
    WHEN ((effect)::text = 'INCREASE'::text) THEN 'DEBIT'::text
    ELSE 'CREDIT'::text
END) STORED,
    currency character(3) NOT NULL,
    posted_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT ck_financial_ledger_amount CHECK (((amount > (0)::numeric) AND ((((effect)::text = 'INCREASE'::text) AND (delta_amount = amount)) OR (((effect)::text = 'DECREASE'::text) AND (delta_amount = (- amount)))))),
    CONSTRAINT ck_financial_ledger_currency CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT ck_financial_ledger_effect CHECK (((effect)::text = ANY ((ARRAY['INCREASE'::character varying, 'DECREASE'::character varying])::text[])))
);

