    recorded_at timestamp with time zone NOT NULL,
    create_idempotency_key character varying(160) CONSTRAINT inbound_receiving_discrepancy_c_create_idempotency_key_not_null NOT NULL,
    create_request_hash character varying(64) NOT NULL,
