    CONSTRAINT ck_inbound_discrepancy_text CHECK ((((length(btrim((unit)::text)) >= 1) AND (length(btrim((unit)::text)) <= 32)) AND (upper(btrim((unit)::text)) = (unit)::text) AND ((length(btrim((reason)::text)) >= 1) AND (length(btrim((reason)::text)) <= 2000)) AND ((expected_batch_reference IS NULL) OR ((length(btrim((expected_batch_reference)::text)) >= 1) AND (length(btrim((expected_batch_reference)::text)) <= 160))) AND ((observed_batch_reference IS NULL) OR ((length(btrim((observed_batch_reference)::text)) >= 1) AND (length(btrim((observed_batch_reference)::text)) <= 160))) AND ((observation_notes IS NULL) OR ((length(btrim((observation_notes)::text)) >= 1) AND (length(btrim((observation_notes)::text)) <= 2000))))),
    CONSTRAINT ck_inbound_discrepancy_time CHECK ((recorded_at <= COALESCE(submitted_at, recorded_at))),
    CONSTRAINT ck_inbound_discrepancy_transition CHECK (((((status)::text = 'PENDING_EVIDENCE'::text) AND (version = 0) AND (evidence_object_id IS NULL) AND (submitted_by_membership_id IS NULL) AND (submitted_at IS NULL) AND (submit_idempotency_key IS NULL) AND (submit_request_hash IS NULL)) OR (((status)::text = 'READY_FOR_REVIEW'::text) AND (version = 1) AND (evidence_object_id IS NOT NULL) AND (submitted_by_membership_id IS NOT NULL) AND (submitted_at IS NOT NULL) AND (submit_idempotency_key IS NOT NULL) AND (submit_request_hash IS NOT NULL))))
);

