    CONSTRAINT ck_inventory_transfer_status CHECK (((((status)::text = 'REQUESTED'::text) AND (transferred_quantity = (0)::numeric) AND (dispatched_at IS NULL) AND (received_at IS NULL) AND (destination_lot_id IS NULL) AND (source_quantity_after IS NULL) AND (source_version_after IS NULL) AND (destination_quantity_before IS NULL) AND (destination_quantity_after IS NULL) AND (destination_version_after IS NULL) AND (completed_at IS NULL) AND (source_lot_status_at_dispatch IS NULL)) OR (((status)::text = 'IN_TRANSIT'::text) AND (transferred_quantity = requested_quantity) AND (dispatched_at IS NOT NULL) AND (received_at IS NULL) AND (destination_lot_id IS NULL) AND (source_quantity_after IS NOT NULL) AND (source_quantity_after = (source_quantity_before - transferred_quantity)) AND (source_version_after > source_version_before) AND (destination_quantity_before IS NULL) AND (destination_quantity_after IS NULL) AND (destination_version_after IS NULL) AND (completed_at IS NULL) AND (source_lot_status_at_dispatch IS NOT NULL)) OR (((status)::text = 'RECEIVED'::text) AND (transferred_quantity = requested_quantity) AND (received_at IS NOT NULL) AND (completed_at IS NOT NULL) AND (destination_lot_id IS NOT NULL) AND (destination_quantity_before IS NOT NULL) AND (destination_quantity_after IS NOT NULL) AND (destination_quantity_after = (destination_quantity_before + transferred_quantity)) AND (destination_version_after IS NOT NULL) AND (((dispatched_at IS NULL) AND (source_lot_status_at_dispatch IS NULL)) OR ((dispatched_at IS NOT NULL) AND (source_lot_status_at_dispatch IS NOT NULL) AND (source_version_after > source_version_before) AND (source_quantity_after = (source_quantity_before - transferred_quantity))))))),
    CONSTRAINT ck_inventory_transfer_versions CHECK (((source_version_before >= 0) AND ((source_version_after IS NULL) OR (source_version_after > source_version_before)) AND ((destination_version_after IS NULL) OR (destination_version_after >= 0)) AND (version >= 0)))
);

