CREATE TABLE warehouse.physical_allocation_substitution_request (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    fulfillment_id uuid CONSTRAINT physical_allocation_substitution_reques_fulfillment_id_not_null NOT NULL,
    allocation_id uuid NOT NULL,
    physical_allocation_line_id uuid CONSTRAINT physical_allocation_substit_physical_allocation_line_i_not_null NOT NULL,
    expected_lot_id uuid CONSTRAINT physical_allocation_substitution_reque_expected_lot_id_not_null NOT NULL,
    alternative_lot_id uuid CONSTRAINT physical_allocation_substitution_re_alternative_lot_id_not_null NOT NULL,
    quantity numeric(19,4) NOT NULL,
    unit character varying(32) NOT NULL,
    reason character varying(2000) NOT NULL,
    status character varying(16) DEFAULT 'REQUESTED'::character varying NOT NULL,
    allocation_version bigint CONSTRAINT physical_allocation_substitution_re_allocation_version_not_null NOT NULL,
    actor_membership_id uuid CONSTRAINT physical_allocation_substitution_r_actor_membership_id_not_null NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    CONSTRAINT ck_physical_allocation_substitution_lots CHECK ((expected_lot_id <> alternative_lot_id)),
    CONSTRAINT ck_physical_allocation_substitution_quantity CHECK ((quantity > (0)::numeric)),
    CONSTRAINT ck_physical_allocation_substitution_status CHECK (((status)::text = 'REQUESTED'::text)),
    CONSTRAINT ck_physical_allocation_substitution_text CHECK ((((length(btrim((unit)::text)) >= 1) AND (length(btrim((unit)::text)) <= 32)) AND ((length(btrim((reason)::text)) >= 1) AND (length(btrim((reason)::text)) <= 2000)))),
    CONSTRAINT ck_physical_allocation_substitution_version CHECK ((allocation_version >= 0))
);

