    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    actor_membership_id uuid NOT NULL,
    CONSTRAINT ck_safety_stock_quantity CHECK ((quantity >= (0)::numeric)),
    CONSTRAINT ck_safety_stock_unit CHECK (((length(btrim((unit)::text)) >= 1) AND (length(btrim((unit)::text)) <= 32))),
    CONSTRAINT ck_safety_stock_version CHECK ((version >= 0))
);

