CREATE TABLE warehouse.selection_snapshot (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    purchase_request_id uuid,
    sales_order_id uuid,
    warehouse_id uuid NOT NULL,
    explanation jsonb NOT NULL,
    origin_latitude numeric(10,7),
    origin_longitude numeric(10,7),
    destination_latitude numeric(10,7),
    destination_longitude numeric(10,7),
    distance_km numeric(12,3),
    duration_seconds bigint,
    calculated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT ck_selection_snapshot_target CHECK (((purchase_request_id IS NOT NULL) OR (sales_order_id IS NOT NULL)))
);

--
-- Name: stock_movement; Type: TABLE; Schema: warehouse; Owner: -
--

CREATE TABLE warehouse.stock_movement (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    warehouse_id uuid NOT NULL,
    zone_id uuid NOT NULL,
    lot_id uuid NOT NULL,
    catalog_item_id character varying(64) NOT NULL,
    movement_type character varying(32) NOT NULL,
    quantity numeric(19,4) NOT NULL,
    unit character varying(32) NOT NULL,
    quantity_before numeric(19,4) NOT NULL,
    quantity_after numeric(19,4) NOT NULL,
    reserved_before numeric(19,4) NOT NULL,
    reserved_after numeric(19,4) NOT NULL,
    reason character varying(2000),
    actor_membership_id uuid,
    correlation_id character varying(160) NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    sku_id uuid NOT NULL,
    CONSTRAINT ck_movement_quantity CHECK ((quantity > (0)::numeric)),
    CONSTRAINT ck_movement_type CHECK (((movement_type)::text = ANY ((ARRAY['INBOUND_RECEIPT'::character varying, 'ADJUSTMENT_IN'::character varying, 'ADJUSTMENT_OUT'::character varying, 'WASTE'::character varying, 'RESERVATION'::character varying, 'RESERVATION_RELEASE'::character varying, 'RESERVATION_EXPIRATION'::character varying, 'OUTBOUND_CONSUMPTION'::character varying, 'TRANSFER_OUT'::character varying, 'TRANSFER_IN'::character varying])::text[])))
);

--
-- Name: storage_zone; Type: TABLE; Schema: warehouse; Owner: -
--

CREATE TABLE warehouse.storage_zone (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    warehouse_id uuid NOT NULL,
    code character varying(32) NOT NULL,
    name character varying(160) NOT NULL,
    zone_type character varying(16) NOT NULL,
    temperature_min numeric(9,4),
    temperature_max numeric(9,4),
    status character varying(16) DEFAULT 'ACTIVE'::character varying NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT ck_zone_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'SUSPENDED'::character varying])::text[]))),
    CONSTRAINT ck_zone_temperature CHECK (((temperature_min IS NULL) OR (temperature_max IS NULL) OR (temperature_min <= temperature_max))),
    CONSTRAINT ck_zone_type CHECK (((zone_type)::text = ANY ((ARRAY['AMBIENT'::character varying, 'CHILLED'::character varying, 'FROZEN'::character varying, 'QUARANTINE'::character varying])::text[])))
);

