    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT ck_warehouse_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'SUSPENDED'::character varying])::text[])))
);

--
-- Name: warehouse_service_configuration; Type: TABLE; Schema: warehouse; Owner: -
--

CREATE TABLE warehouse.warehouse_service_configuration (
    warehouse_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    service_status character varying(16) DEFAULT 'OPERATIONAL'::character varying NOT NULL,
    service_area_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    priority integer DEFAULT 0 NOT NULL,
    preferred boolean DEFAULT false NOT NULL,
    operating_hours_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    supported_fulfillment_types jsonb DEFAULT '[]'::jsonb CONSTRAINT warehouse_service_configura_supported_fulfillment_type_not_null NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    latitude numeric(10,7),
    longitude numeric(10,7),
    CONSTRAINT ck_warehouse_service_configuration_coordinates CHECK ((((latitude IS NULL) AND (longitude IS NULL)) OR (((latitude >= ('-90'::integer)::numeric) AND (latitude <= (90)::numeric)) AND ((longitude >= ('-180'::integer)::numeric) AND (longitude <= (180)::numeric))))),
    CONSTRAINT ck_warehouse_service_configuration_status CHECK (((service_status)::text = ANY ((ARRAY['OPERATIONAL'::character varying, 'CLOSED'::character varying, 'BLOCKED'::character varying])::text[])))
);

